function range(v,min,max,blank=false,integer=false){if(v===''){if(blank)return '';throw Error('Required numeric value is blank');}if(typeof v!=='number'&&typeof v!=='string')throw Error('Invalid numeric value');let n=Number(v);if(!Number.isFinite(n)||n<min||n>max||integer&&!Number.isInteger(n))throw Error('Value outside allowed range '+min+'–'+max);return n;}
