document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let prev=clone(S);try{if(b.dataset.start!==undefined){let q=S.queues[Number(b.dataset.start)],l=row(q.building,q.target);if(q.status!=='selected')return;let bill=costs(l).map(v=>v*(1-S.discount/100));if(bill.some((v,i)=>v>availableStock(i)))throw Error('Recorded stock is below this invoice. Update balances before recording this start.');if(!confirm('Record that you started '+names[q.building]+' '+q.target+' in game? Deduct estimated Food / Metal / Oil '+bill.map(v=>fmt(v,3)+'M').join(' / ')+' from inventory and remove its future invoice. Correct your balances if the live bill differs.'))return;S.resources.forEach((r,i)=>{r.stock-=bill[i];if(num(r.liquid)!==null)r.liquid=Math.max(0,r.liquid-bill[i]);r.evidence='estimated'});q.status='running';q.hours='';notify('Start recorded and estimated invoice deducted once. Correct inventory to actual live balances if the bill differs.');}else if(b.dataset.complete!==undefined){let q=S.queues[Number(b.dataset.complete)];if(!confirm('Record that '+names[q.building]+' '+q.target+' is completed/claimed in game?'))return;S.buildings[q.building]=q.target;q.target++;q.status='idle';q.hours='';S.accountEvidence='reported';}else if(b.dataset.claim){let r=S.research[b.dataset.claim];if(!confirm('Record that this completion was claimed in game? Check VS scoring first.'))return;setResearchLevel(b.dataset.claim,Number(r.level)+1);r.availability='unknown';r.held=false;r.evidence='User edited; unverified';}else return;S=validate(S);save();refreshMount();}catch(e){S=prev;notify(e.message);refreshMount();}});
