function actionDecisions(){let jobs=routeJobs(),s=schedule({realistic:true}),actions=[],selected=jobs.find(j=>!j.active&&S.queues.some(q=>q.status==='selected'&&q.building===j.id&&q.target===j.lv));if(selected){let q=S.queues.findIndex(x=>x.status==='selected'&&x.building===selected.id&&x.target===selected.lv);actions.push(buildAction(selected,{q}));}else{let candidates=jobs.filter(j=>!j.active&&j.tier===1&&j.lv===Number(S.buildings[j.id])+1);let chain=new Set(criticalChain(s).map(j=>j.key));candidates.sort((a,b)=>Number(chain.has(b.key))-Number(chain.has(a.key))||a.lv-b.lv);if(candidates[0])actions.push(buildAction(candidates[0]));}
let active=jobs.filter(j=>j.active&&!j.held),follow=active.map(a=>({a,j:jobs.find(j=>j.id===a.id&&j.lv===a.lv+1&&!j.active&&j.tier===1)})).filter(x=>x.j&&x.j.l.prerequisites.every(p=>p.building_ids?.some(id=>Number(S.buildings[id])>=p.minimum_level)));follow.sort((a,b)=>Number(b.j.id===5044)-Number(a.j.id===5044)||(a.a.remaining??Infinity)-(b.a.remaining??Infinity));if(follow[0])actions.push(buildAction(follow[0].j,{after:true,active:follow[0].a}));else{let alternative=jobs.find(j=>!j.active&&j.tier===1&&j.lv===Number(S.buildings[j.id])+1&&!actions.some(a=>a.title.includes(names[j.id])));if(alternative)actions.push(buildAction(alternative));}
let research=researchDecisions(),held=research.find(r=>S.research[r.id].availability==='held'),pick=held||research.find(r=>r.state==='Do Now')||research[0];if(pick){let eligible=pick.state==='Do Now',isHeld=!!held,missing=pick.missing;actions.push({kind:'Research',state:eligible?'Do Now':isHeld?'Needs Verification':pick.state==='Hold for VS'?'Waiting':'Needs Verification',title:isHeld?'Keep '+pick.t.name+' completion held':eligible?pick.t.name+', Lv'+pick.n.n+' → '+pick.n.l.level:'Verify research before investing',why:isHeld?'The completion is recorded as held; it has not raised the effective level.':eligible?'Highest-ranked verified candidate for your selected '+S.researchFocus+' objective. '+pick.value:'No research start is recommended from the current evidence.',when:isHeld?'Claim manually only if the reviewed event rules call for it':eligible?'Now, within the reviewed event window':pick.state==='Hold for VS'?'During the verified VS window':'After the missing account information is confirmed',cost:eligible&&pick.bill?pick.bill.map((v,i)=>resourceNames[i]+' '+fmt(v,3)+'M').join(' · '):'No new research spend recommended',time:eligible?fmt(pick.qh)+'h estimated research time':'',next:isHeld?'Record the claim after doing it in game; the speed and plan will recalculate.':eligible?'Claimed benefits update the route, forecast and next recommendation.':'Review '+(missing.slice(0,3).join('; ')||'funding, strategic value and event timing')+'.',missing:eligible?[]:missing,button:eligible?'Review candidate':'Update research info',quick:'research',tech:pick.id});}
if(!actions.length)actions.push({kind:'Route complete in your record',state:'Needs Verification',title:'Verify the T9 training tooltip',why:'The required building levels are recorded. Troop access and training costs remain separate checks.',when:'Now, in game',cost:'Training cost unknown',next:'Record verified unlock information without assuming troops are trained.',quick:'verified',button:'Record verification'});return actions.slice(0,3);}
function renderActionCenter(){let actions=actionDecisions();$('commandContext').textContent='Base '+S.buildings[1001]+' → Base 27 → Camp 1 Lv27 → T9. '+(S.funding==='unlimited'?'Advanced analysis is hypothetical; these actions still use funded conditions.':'Your next actions use current funding and account evidence.');$('actions').innerHTML=actions.map((a,i)=>`<article class="action-card ${i===0?'lead':''}" data-action-card><div class="kind">${esc(a.kind)}${i===0?' · your next move':''}</div><span class="state ${a.state==='Do Now'?'now':a.state==='Needs Verification'?'verify':'wait'}">${a.state}</span><h2>${esc(a.title)}</h2><p class="reason">${esc(a.why)}</p><dl class="decision-fields"><div><dt>WHEN</dt><dd>${esc(a.when)}</dd></div><div><dt>COST</dt><dd>${esc(a.cost)}${a.time?'<small class="costline">'+esc(a.time)+'</small>':''}</dd></div><div><dt>NEXT</dt><dd>${esc(a.next)}</dd></div></dl>${a.missing?.length?`<details><summary>${a.missing.length} checks before a research decision</summary><ul>${a.missing.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul></details>`:''}<button ${i===0?'class="primary"':''} data-quick="${a.quick}" ${a.q!==null&&a.q!==undefined?'data-qpick="'+a.q+'"':''} ${a.tech?'data-techpick="'+a.tech+'"':''}>${esc(a.button)}</button></article>`).join('');}
function sevenDayPlan(){let real=schedule({realistic:true}),known=S.queues.map((q,i)=>({...q,q:i})).filter(q=>q.status==='running'&&num(q.hours)!==null),unknown=S.queues.map((q,i)=>({...q,q:i})).filter(q=>['running','held'].includes(q.status)&&num(q.hours)===null),earliest=known.slice().sort((a,b)=>a.hours-b.hours)[0],first=unknown.length?'First finish is not yet known. Enter '+unknown.map(q=>'Queue '+(q.q+1)).join(' and ')+' remaining time.':earliest?'Queue '+(earliest.q+1)+' finishes first: '+names[earliest.building]+' '+earliest.target+', about '+fmt(earliest.hours)+'h remaining.':'No running build with a finish time is recorded.';let unverifiedPlan=strictResourceGaps().length>0||S.accountEvidence!=='verified';let days=Array.from({length:7},(_,i)=>({day:i+1,events:[]}));for(let q of S.queues.filter(x=>x.status==='selected'))days[0].events.push('Confirm selected '+names[q.building]+' '+q.target+' and its invoice; not assumed started.');for(let q of known){if(q.hours<=168)days[Math.min(6,Math.max(0,Math.ceil(q.hours/24)-1))].events.push('Q'+(q.q+1)+': '+names[q.building]+' '+q.target+' expected to finish; record completion manually.');}for(let j of real.result.filter(j=>!j.active&&j.start<168)){days[Math.min(6,Math.floor(j.start/24))].events.push((unverifiedPlan?'Conditional model: Q':'Model: Q')+(j.q+1)+' starts '+names[j.id]+' '+j.lv+' if the live invoice and eligibility match.');}let next=[];for(let q of S.queues.map((q,i)=>({...q,q:i}))){let proposed=real.result.filter(j=>!j.active&&j.q===q.q).sort((a,b)=>a.start-b.start)[0],current=q.status==='running'?names[q.building]+' '+q.target:q.status==='selected'?'Selected: '+names[q.building]+' '+q.target:q.status==='held'?'Held: '+names[q.building]+' '+q.target:'Free';next.push({q:q.q,current,next:proposed?names[proposed.id]+' '+proposed.lv+' · '+fmt(proposed.start)+'h from now':q.status==='selected'?'Confirm the selected start first':q.status==='running'&&q.building===5044&&q.target<24?'Warrior '+(q.target+1)+' after completion, if funded and eligible':'Next Tier 1 start is conditional on timers, prerequisites and funding'});}let optional=withOptional(real),event=liveEvent(),holds=D.research.filter(t=>S.research[t.id].availability==='held'),research=holds.length?holds.map(t=>t.name).join(', ')+': keep held; '+(event.open?'review the scoring trigger before a manual claim':event.future?'review at the entered VS opening':'event time or scoring rules need verification')+'.':researchDecisions().some(r=>r.state==='Do Now')?'A verified research candidate is available; review the shortlist before starting.':'Do not schedule a new research start until the missing eligibility, slot, bonus, invoice and event checks are complete.';return {first,days,next,research,optional:optional.optional||[],optionalReason:optional.priorityReason,conditional:unknown.length>0||!real.complete||unverifiedPlan};}
function renderWeek(){let p=sevenDayPlan();$('weeklyPlan').innerHTML=`<div class="scenario-note"><strong>${esc(p.first)}</strong></div><div class="week-grid">${p.days.map(d=>`<div class="day"><b>Day ${d.day}</b><p>${esc(d.events.length?d.events.join(' '):p.conditional?'Conditional: continue recorded work; no verified new start or finish.':'Continue the funded schedule; no modeled transition today.')}</p></div>`).join('')}</div><details><summary>Queue-by-queue plan, research & protected resources</summary>${p.next.map(q=>`<div class="plan-line"><strong>Queue ${q.q+1} · ${esc(q.current)}</strong>${esc(q.next)}</div>`).join('')}<div class="plan-line"><strong>Research / VS</strong>${esc(p.research)}</div><div class="plan-line"><strong>Protected resources</strong>${esc(S.resources.map((r,i)=>resourceNames[i]+': '+(r.reserve===''?'reserve unknown':fmt(r.reserve)+'M reserve')+'; next required invoices remain protected').join(' · '))}</div><div class="plan-line"><strong>Tier 2</strong>${esc(p.optional.length?p.optional.map(j=>names[j.id]+' '+j.lv+' fits a verified idle gap').join('; '):p.optionalReason)}</div></details>`;}
const milestoneDefs=[{key:'base24',id:1001,lv:24,label:'Base 24'},{key:'base25',id:1001,lv:25,label:'Base 25'},{key:'base26',id:1001,lv:26,label:'Base 26'},{key:'base27',id:1001,lv:27,label:'Base 27'},{key:'camp27',id:1020,lv:27,label:'Camp 1 Lv27'},{key:'t9',id:null,lv:0,label:'T9'}];
function milestoneModel(key){let m=milestoneDefs.find(x=>x.key===key)||milestoneDefs[1];if(m.key==='t9'){let verified=S.staging[0].verified,done=S.buildings[1020]>=27&&S.buildings[1001]>=27;return {...m,status:done&&verified?'Level path met · confirm troop access':done?'Needs Verification':'Waiting on Camp 1 Lv27',needs:['Base ≥ 27','Soldier Training Camp 1 ≥ 27','Live T9 tooltip and training invoice'],cost:null,hours:null,confidence:'User-specified unlock path; live tooltip '+(verified?'verified by you':'unverified')};}let l=row(m.id,m.lv),done=S.buildings[m.id]>=m.lv,job=routeJobs().find(j=>j.id===m.id&&j.lv===m.lv),active=job?.active,met=S.buildings[m.id]>=m.lv-1&&l.prerequisites.every(p=>p.building_ids?.some(id=>Number(S.buildings[id])>=p.minimum_level)),bill=costs(l).map(c=>c*(1-S.discount/100)),funded=bill.every((c,i)=>c<=availableStock(i)-(num(S.resources[i].reserve)||0)),canProve=S.accountEvidence==='verified'&&!strictResourceGaps().length;return {...m,status:done?'Completed in account':active?'Underway · '+(job.remaining===null?'timer unknown':fmt(job.remaining)+'h left'):!met?'Waiting on prerequisite':!funded?'Blocked by resources':canProve?'Ready to start':'Needs Verification',needs:[...(done?[]:[names[m.id]+' ≥ '+(m.lv-1)]),...l.prerequisites.map(gateText)],cost:done?null:bill,hours:done?0:l.base_time_seconds/3600/(1+effectiveSpeeds().build/100),raw:l.base_time_seconds/3600,confidence:'Prerequisites, raw time and gross costs: client source. Completed level: '+S.accountEvidence+'. Discount / total speed: modeled.',done};}
function renderMilestones(){let models=milestoneDefs.map(m=>milestoneModel(m.key));$('milestones').innerHTML=models.map((m,i)=>`<button class="${selectedMilestone===m.key?'selected':''}" data-milestone="${m.key}" aria-pressed="${selectedMilestone===m.key}"><span class="num">${String(i+1).padStart(2,'0')}</span><strong>${m.label}</strong><span class="mark">${m.done?'✓ Complete':m.key==='t9'?'Unlock goal':m.status==='Underway · timer unknown'?'Underway':m.status==='Needs Verification'?'Verify':m.status==='Blocked by resources'?'Funding gap':'Pending'}</span></button>`).join('');let m=milestoneModel(selectedMilestone);$('milestoneDetail').innerHTML=`<span class="state ${m.done?'now':'wait'}">${esc(m.status)}</span><h2 style="margin-top:12px">${m.label}${m.key==='camp27'?' → T9 path':''}</h2><div class="milestone-content"><div><h3>What needs to happen</h3><ul class="compact-list">${m.needs.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul><p class="micro">Previous levels of this same building are also required. The full route budget includes every missing level.</p></div><div><h3>Milestone invoice & workload</h3><p>${m.cost?m.cost.map((v,i)=>resourceNames[i]+' '+fmt(v,3)+'M').join(' · '):m.done?'Already completed in your account record':'Troop training invoice unknown'}</p><p>${m.hours===null?'Training time unknown':fmt(m.hours)+'h modeled for this level'+(m.raw?' · '+fmt(m.raw)+' raw work hours':'')+'.'}</p><p class="micro">${esc(m.confidence)}</p></div></div>`;}
function renderResourceCards(){$('resourceModeNotice').textContent=S.funding==='unlimited'?'HYPOTHETICAL analysis: invoices may create negative model balances. These are theoretical shortages, never actual spendable inventory. Home actions and the seven-day plan still use funded conditions.':'Funded analysis: starts require enough recorded spendable resources after reserves. Unknown balances or clocks remain conditional. Summaries above never use hypothetical negative balances.';document.querySelectorAll('[data-analysis-mode]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.analysisMode===S.funding)));let total=totals(routeJobs()),values=S.resources.map((r,i)=>({i,r,available:availableStock(i),required:total[i],gap:Math.max(0,total[i]-availableStock(i)+(num(r.reserve)||0))}));$('resourceSummary').innerHTML=values.map(({i,r,available,required,gap})=>`<article class="resource-card"><h3>${resourceNames[i]}</h3><span class="micro">${num(r.liquid)===null?'Immediate availability unverified · combined estimate':'Immediately available, before reserve'}</span><strong class="big">${fmt(available,1)}M</strong><dl><dt>Required for route</dt><dd>${fmt(required,1)}M</dd><dt>Protected reserve</dt><dd>${r.reserve===''?'Unknown':fmt(r.reserve)+'M'}</dd><dt>${num(r.liquid)===null?'Estimated gap':'Shortfall after reserve'}</dt><dd class="${gap?'bad':'good'}">${fmt(gap,1)}M</dd><dt>Unopened boxes</dt><dd>${r.boxes===''?'Not separated':fmt(r.boxes)+'M'}</dd><dt>Net income / day</dt><dd>${r.income===''?'Unknown':fmt(r.income)+'M'}</dd><dt>Funding pace</dt><dd>${!gap?'Covered in model':num(r.income)>0?'~'+fmt(gap/r.income)+'d at this rate':r.income===''?'Unknown':'No positive inflow'}</dd></dl></article>`).join('');let ranked=values.filter(x=>x.gap>0);let comparableIncome=ranked.length>0&&ranked.every(x=>num(x.r.income)>0);ranked.sort((a,b)=>comparableIncome?b.gap/b.r.income-a.gap/a.r.income:b.gap-a.gap);let priority=ranked.length?'Resource priority: '+ranked.map(x=>resourceNames[x.i]+' ('+fmt(x.gap,1)+'M gap'+(num(x.r.income)>0?', ~'+fmt(x.gap/x.r.income)+'d at entered net income':'')+')').join(' → ')+'. Protect required invoices before optional research or staging. Funding-pace estimates assume the entered net income continues; they are not construction ETAs.':'The recorded balance covers modeled building invoices; training, healing and unknown reserves remain separate.';let unsplit=S.resources.some(r=>num(r.liquid)===null);$('resourcePriorities').textContent=priority+' '+(unsplit?'Combined inventory includes boxes whose immediately available portion is unknown. Separate the balances before treating them as ready to spend.':'Unopened boxes are excluded from immediately spendable funding until you update the opened balance.');$('commandFunding').innerHTML=`<p>${esc(ranked.length?'Save and gather '+ranked.slice(0,2).map(x=>resourceNames[x.i]).join(' and ')+' first.':'Current recorded funding covers the route.')}</p><p class="micro">${values.map(x=>resourceNames[x.i]+': '+fmt(x.gap,1)+'M '+(num(x.r.liquid)===null?'estimated gap':'shortfall')).join(' · ')}. ${S.resources.some(r=>r.reserve==='')?'Protected reserves still need to be entered.':''}</p>`;let p=withOptional(schedule({realistic:true}));$('commandOptional').innerHTML=p.optional?.length?`<p>${esc(p.optional.map(j=>names[j.id]+' '+j.lv+' fits a genuine spare gap.').join(' '))}</p>`:'<p>No Tier 2 upgrade is currently recommended.</p><p class="micro">'+esc(p.priorityReason)+'</p>';renderResourceEditors();}
function renderResourceEditors(){if(document.activeElement?.closest?.('#resourceEditors')){syncResourceInputs();return;}$('resourceEditors').innerHTML=S.resources.map((r,i)=>`<div class="res-edit"><h3>${resourceNames[i]}</h3>${[['stock','Combined inventory M (including boxes)'],['liquid','Immediately available M'],['boxes','Unopened boxes M'],['reserve','Protected reserve M'],['income','Net income M/day']].map(([k,l])=>`<label>${l}<input aria-label="${resourceNames[i]} ${l}" data-resource="${i}" data-field="${k}" type="number" ${k==='income'?'':'min="0"'} step="any" value="${r[k]}" placeholder="Unknown"></label>`).join('')}<label>Balance confidence<select data-resource="${i}" data-field="evidence">${['estimated','verified','unknown'].map(x=>`<option ${r.evidence===x?'selected':''}>${x}</option>`).join('')}</select></label></div>`).join('');}
function syncResourceInputs(){document.querySelectorAll('[data-resource][data-field]').forEach(el=>{if(el!==document.activeElement)el.value=S.resources[Number(el.dataset.resource)][el.dataset.field];});}
function renderShortlist(){let rows=researchDecisions(),show=rows.slice(0,4);$('researchFocus').value=S.researchFocus;$('researchShortlist').innerHTML=show.map((r,i)=>`<article class="research-card"><span class="state ${r.state==='Do Now'?'now':r.state==='Insufficient Data'?'verify':'wait'}">${r.state}</span><h3>${i+1}. ${esc(r.t.name)}${r.n?' '+r.n.n+'→'+r.n.l.level:''}</h3><p>${esc(r.value)}</p><p class="numbers">Gain ${r.n?fmt(r.gain*100,2)+' pp':'unknown'} · ${r.qh===null?'Research time unknown':fmt(r.qh)+'h research (modeled)'}</p><p class="numbers">${r.bill?r.bill.map((v,i)=>resourceNames[i]+' '+fmt(v,3)+'M').join(' · '):'Next invoice unknown until the current level is entered.'}</p><p class="micro">${r.missing.length?'Missing: '+esc(r.missing.slice(0,3).join('; '))+(r.missing.length>3?' + '+(r.missing.length-3)+' more checks.':''):'Live eligibility, invoice, balances and selected speed inputs verified by you.'}</p>${r.missing.length?`<details><summary>All verification checks</summary><ul>${r.missing.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul></details>`:''}<button class="linklike" data-quick="research" data-techpick="${r.id}">Review this research →</button></article>`).join('');}
function renderActions(jobs,total,s){renderPreviousActions(jobs,total,s);renderActionCenter();renderWeek();renderMilestones();renderResourceCards();renderShortlist();window.ZRFighter?.renderActionLinks();}
function showPage(page){if(!['command','roadmap','resources','account'].includes(page))return;currentPage=page;for(let p of ['command','roadmap','resources','account']){$('page-'+p).hidden=p!==page;$('nav-'+p).setAttribute('aria-selected',String(p===page));}window.scrollTo?.({top:0,behavior:'instant'});}
document.addEventListener('keydown',e=>{let pages=['command','roadmap','resources','account'],p=e.target.dataset?.goto;if(!p||!e.target.closest('nav'))return;let i=pages.indexOf(p),target=e.key==='ArrowRight'?pages[(i+1)%4]:e.key==='ArrowLeft'?pages[(i+3)%4]:e.key==='Home'?pages[0]:e.key==='End'?pages[3]:null;if(target){e.preventDefault();showPage(target);$('nav-'+target).focus();}});
let quickQueue=2,quickTech=1015;
function openQuick(category='queues',q=null,tech=null){quickCategory=category;if(q!==null)quickQueue=Number(q);if(tech!==null)quickTech=Number(tech);renderQuick();if(!$('progressDialog').open)$('progressDialog').showModal();}
function renderQuick(){let body='';$('quickNotice').textContent='Changes marked “save” are recorded only when you press the button. Other field edits save immediately.';if(quickCategory==='queues'){let q=S.queues[quickQueue],defaultAction=q.status==='selected'?'start':q.status==='running'?'timer':q.status==='held'?'complete':'timer';body=`<label>Construction queue<select id="quickQueue">${S.queues.map((x,i)=>`<option value="${i}" ${i===quickQueue?'selected':''}>Queue ${i+1} · ${names[x.building]} ${x.target} · ${x.status}</option>`).join('')}</select></label><label>What changed?<select id="quickBuildAction"><option value="timer" ${defaultAction==='timer'?'selected':''}>Update remaining time</option><option value="start" ${defaultAction==='start'?'selected':''}>I started this build in game</option><option value="complete" ${defaultAction==='complete'?'selected':''}>I completed / claimed it in game</option></select></label><label>Remaining hours (for a timer update)<input id="quickHours" type="number" min="0" step="any" value="${q.hours}" placeholder="Unknown"></label><p>${q.status==='selected'?'This build is selected, not recorded as started.':'Effective completed level: '+S.buildings[q.building]+'. An active target is not completed.'} Recording a start deducts its estimated invoice once; correct balances if the live bill differs.</p><button id="applyQuickBuild" class="primary">Save build update</button><button data-secondary="queues">Choose or correct a building / queue</button>`;}else if(quickCategory==='resources'){body='<p>Amounts are in millions. Supplying available stock and boxes updates the combined total; unopened boxes are kept out of spendable funding.</p>'+S.resources.map((r,i)=>`<div class="quick-res"><h3>${resourceNames[i]}</h3><div class="two">${[['liquid','Immediately available M'],['boxes','Unopened boxes M'],['reserve','Protected reserve M'],['income','Net income M/day']].map(([k,l])=>`<label>${l}<input data-resource="${i}" data-field="${k}" type="number" step="any" ${k==='income'?'':'min="0"'} value="${r[k]}" placeholder="Unknown"></label>`).join('')}</div><label>Balance confidence<select data-resource="${i}" data-field="evidence">${['estimated','verified','unknown'].map(x=>`<option ${r.evidence===x?'selected':''}>${x}</option>`).join('')}</select></label></div>`).join('')+'<button id="doneQuick" class="primary">Done</button>';}else if(quickCategory==='research'){let t=D.research.find(x=>x.id===quickTech)||D.research[0],r=S.research[t.id];body=`<label>Technology<select id="quickTech">${D.research.map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><div class="two"><label>Effective claimed level<input data-level="${t.id}" type="number" min="0" max="${t.max_level}" step="1" value="${esc(r.level)}" placeholder="Unknown"></label><label>Next-level state<select data-status="${t.id}">${[['unknown','Unknown'],['available','Verified available'],['running','Running'],['held','Completed, held']].map(([x,l])=>`<option value="${x}" ${r.availability===x?'selected':''}>${l}</option>`).join('')}</select></label></div><label>Level evidence<select data-evidence="${t.id}">${[...new Set([r.evidence,'Unknown','User edited; unverified','Verified by you'])].map(x=>`<option ${x===r.evidence?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label class="check"><input data-invoice="${t.id}" type="checkbox" ${r.invoiceVerified?'checked':''}>I checked this next-level invoice in game</label><label>Research slot<select id="researchSlot">${[['unknown','Unknown'],['free','Confirmed free'],['running','Occupied']].map(([x,l])=>`<option value="${x}" ${S.researchSlot===x?'selected':''}>${l}</option>`).join('')}</select></label><label class="check"><input id="heldReviewed" type="checkbox" ${S.heldReviewed?'checked':''}>I reviewed all running / held completions</label><p>A held target does not raise the effective level. Claims stay manual in the VS panel.</p><button data-secondary="vs">Review VS window & held claims</button><button id="doneQuick" class="primary">Done</button>`;}else{let e=effectiveSpeeds();body=`<p>Record live information, not an assumed upgrade. Account and research evidence remain independent.</p><label>Building account evidence<select id="accountEvidenceQuick"><option value="reported" ${S.accountEvidence==='reported'?'selected':''}>Reported / last known</option><option value="verified" ${S.accountEvidence==='verified'?'selected':''}>Verified by me in game</option></select></label><div class="two"><label>Actual total building speed, %<input id="quickActualBuild" type="number" min="0" step="any" value="${e.build}"></label><label>Actual total research speed, %<input id="quickActualResearch" type="number" min="0" step="any" value="${e.research}"></label></div><button id="applyVerifiedBonuses">Record these totals as verified</button><label class="check"><input id="vsReviewed" type="checkbox" ${S.vsReviewed?'checked':''}>I reviewed the VS timing and scoring rules</label><p>The actual window and scoring trigger must also be entered. Verification alone does not invent an event schedule.</p><button data-secondary="vs">Enter VS window / trigger</button><button data-secondary="staging">Record camp unlock tooltips</button><button id="doneQuick" class="primary">Done</button>`;}$('quickContent').innerHTML=body;}
function openSecondary(which){$('progressDialog').close?.();let map={queues:['account','queueEditor'],vs:['account','vsEditor'],staging:['roadmap','stagingDetail']},[page,id]=map[which]||['account','buildingEditor'];showPage(page);$(id).open=true;$(id).scrollIntoView?.({block:'start'});}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.analysisMode){S.funding=b.dataset.analysisMode;S.zeroTimers=b.dataset.analysisMode==='unlimited';$('funding').value=S.funding;$('zeroTimers').checked=S.zeroTimers;save();render();}else if(b.dataset.goto)showPage(b.dataset.goto);else if(b.dataset.milestone){selectedMilestone=b.dataset.milestone;renderMilestones();}else if(b.dataset.quick)openQuick(b.dataset.quick,b.dataset.qpick??null,b.dataset.techpick??null);else if(b.dataset.secondary)openSecondary(b.dataset.secondary);else if(['closeProgress','doneQuick'].includes(b.id))$('progressDialog').close();else if(b.id==='applyQuickBuild'){let q=S.queues[quickQueue],action=$('quickBuildAction').value;if(action==='timer'){if(!$('quickHours').reportValidity())return;let el={dataset:{queue:String(quickQueue),qfield:'hours'},value:$('quickHours').value,reportValidity:()=>true};change(el);$('quickNotice').textContent='Remaining time saved. All planning views were refreshed.';}else{let allowed=action==='start'?q.status==='selected':['running','held'].includes(q.status);if(!allowed){$('quickNotice').textContent=action==='start'?'Choose a selected build first. A running build cannot be started twice.':'This queue has no running or held completion to record.';return;}let old=q.status;document.querySelector('[data-'+(action==='start'?'start':'complete')+'="'+quickQueue+'"]').click();if(S.queues[quickQueue].status!==old){$('progressDialog').close();notify('Build update saved; the action plan, invoices and schedule were refreshed.');}}}else if(b.id==='applyVerifiedBonuses'){let a=$('quickActualBuild'),r=$('quickActualResearch');if(!a.reportValidity()||!r.reportValidity())return;let prev=clone(S);try{S.buildSpeed=range(a.value,0,10000);S.researchSpeed=range(r.value,0,10000);S.bonusMode='manual';S.speedEvidence='verified';S.researchEvidence='verified';S=validate(S);save();render();$('quickNotice').textContent='Verified total bonuses saved. Claimed-level changes will adjust them by the marginal gain.';}catch(err){S=prev;$('quickNotice').textContent=err.message;}}});
document.addEventListener('change',e=>{if(e.target.id==='quickQueue'){quickQueue=Number(e.target.value);renderQuick();}else if(e.target.id==='quickTech'){quickTech=Number(e.target.value);renderQuick();}else if(e.target.id==='accountEvidenceQuick'){S.accountEvidence=e.target.value;save();render();}});

mount();if(loadError)notify(loadError);else {try{if(localStorage.getItem(KEY))$('saved').textContent='Loaded saved account from this browser';}catch(e){notify('Storage unavailable — export your account to keep changes.');}}setInterval(()=>{renderVS();renderActionCenter();renderWeek();renderShortlist();},30000);
window.dashboard={getState:()=>clone(S),validate,routeJobs,schedule,totals,nextResearch,benefit,effectiveSpeeds,withOptional,priorityAnalysis,availableStock,actionDecisions,researchDecisions,sevenDayPlan,milestoneModel};

window.ZRWorkspace.mount();window.ZRWorkspace.register(KEY,validate);addEventListener('zr-linked',e=>{if(e.detail.key===KEY){try{S=validate(window.ZRWorkspace.read(KEY));refreshMount()}catch(err){notify('Linked account rejected: '+err.message)}}});addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{S=validate(JSON.parse(e.newValue));refreshMount()}catch(err){notify('Other-tab update rejected: '+err.message)}}});

window.ZRCommandAPI={get:()=>clone(S),validate,model:()=>({actions:actionDecisions(),research:researchDecisions(),jobs:routeJobs(),totals:totals(routeJobs()),week:sevenDayPlan(),milestones:milestoneDefs.map(x=>({...x,...milestoneModel(x.key)})),event:liveEvent(),resourceGaps:strictResourceGaps(),catalog:D.research.map(t=>({id:t.id,name:t.name,max_level:t.max_level}))}),patch(p){let before=clone(S);try{S=validate({...S,...p});if(save('Command Center: '+Object.keys(p).join(', '))===false||JSON.stringify(window.ZRWorkspace.read(KEY))!==JSON.stringify(S)){S=before;throw Error('Account could not be saved');}refreshMount();return true;}catch(e){S=before;throw e;}},researchEdit(id,patch){let before=clone(S);try{if(patch.level!==undefined)setResearchLevel(id,patch.level);Object.assign(S.research[id],patch);S=validate(S);if(save('Research '+(D.research.find(t=>t.id===id)?.name||id)+': '+before.research[id].level+' → '+S.research[id].level)===false||JSON.stringify(window.ZRWorkspace.read(KEY))!==JSON.stringify(S))throw Error('Account could not be saved');refreshMount();return true;}catch(e){S=before;throw e;}},refresh(){let raw=window.ZRWorkspace.read(KEY);if(raw)S=validate(raw);refreshMount();},ensure(){if(!window.ZRWorkspace.read(KEY))save();},ready:true};

